(() => {
 if(location.protocol!=='file:')return;
 const fonts={"300":"data:font/ttf;base64,","400":"data:font/ttf;base64,","500":"data:font/ttf;base64,","700":"data:font/ttf;base64,"};
 const masks={"1447b.svg":"data:image/svg+xml;base64,","45477.svg":"data:image/svg+xml;base64,","713c0.svg":"data:image/svg+xml;base64,"};
 const face=(name,weight,url)=>'@font-face{font-family:'+name+';font-weight:'+weight+';font-style:normal;font-display:swap;src:url("'+url+'") format("truetype");}';
 const style=document.createElement('style');
 style.textContent=Object.entries(fonts).map(([weight,url])=>face('CyberHarmony',weight,url)).join('')+face('Harmony',400,fonts[400])+
 '.certificate-pattern{mask-image:url("'+masks['1447b.svg']+'");}'+
 '.editorial-pattern{mask-image:url("'+masks['45477.svg']+'");}'+
 '.editorial-card:nth-child(3) .editorial-pattern{mask-image:url("'+masks['713c0.svg']+'");}';
 document.head.appendChild(style);
})();